    "meaning": "कल्पना पटवारी द्वारा स्वरबद्ध 'दर्शन देखाई दीही / उगी उगी हे आदित मोला' छठ महापर्व के उषा अर्घ्य का अत्यंत भावपूर्ण गीत है। इसमें व्रती तीन दिनों के कठिन निर्जला व्रत के उपरांत शीतल जल में हाथ में सूप लेकर भगवान भास्कर से बादलों की ओट से बाहर आकर शीघ्र दर्शन देने और अपने पावन व्रत को सफल बनाने की प्रार्थना करते हैं।",
