    "meaning": "लोकगायिका देवी द्वारा स्वरबद्ध 'कांच ही बांस के बहंगिया' छठ महापर्व का सर्वकालिक लोकप्रिय व हृदयस्पर्शी पारंपरिक लोकगीत है। इसमें ताजे कच्चे बांस की बहंगी में छठ मइया और सूर्यदेव के लिए पवित्र प्रसाद व फल भरकर घाट ले जाने का जीवंत व आत्मीय वर्णन है। रास्ते में जब कोई राहगीर (बटोहिया) पूछता है कि यह बहंगी किसके लिए जा रही है, तो श्रद्धा से उत्तर दिया जाता है कि यह परम पावन बहंगी साक्षात छठी मइया के चरणों में अर्पण करने जा रही है।",
