    "meaning": "लोकगायिका देवी द्वारा स्वरबद्ध 'कोपि कोपि बोलेली छठिया मइया' छठ महापर्व का अत्यंत प्रिय और पारंपरिक घाट सफाई व सेवा भाव का लोकगीत है। इसमें छठ मइया अपने सेवकों से उलाहना देकर कहती हैं कि उनके घाट पर घास-फूस उग आई है और मकड़ी ने जाला बना लिया है। इस पर सभी सेवक और व्रती श्रद्धा भाव से हाथ जोड़कर मैया को आश्वस्त करते हैं कि वे घाट की सफाई करेंगे, गोबर से लीपकर चंदन छिड़केंगे, चांदनी तानेंगे, बाजा बजवाएंगे और कच्चे दूध से पावन अर्घ्य समर्पित करेंगे।",
