    "lyricsSnippetHindi": "भोरवे में नदिया नहाईला आदित मनाईला हो, बाबा फूलवा अक्षतवा चढ़ाईला सब गुण गाईला हो",
    "lyricsSnippetEnglish": "Bathing in the river at dawn to worship Lord Aditya, offering flowers and sacred akshat with reverent prayers.",
    "lyrics": "भोरवे में नदिया नहाईला आदित मनाईला हो,\n\nबाबा फूलवा अक्षतवा चढ़ाईला सब गुण गाईला हो,\n\nबाबा फूलवा अक्षतवा चढ़ाईला सब गुण गाईला हो ॥\n\nअस धरवाईब सईया अन्हरिया से बोझिल हो,\n\nबाबा अँगने में मांगीला अंजोर ई मथवा नवाईला हो,\n\nबाबा अँगने में मांगीला अंजोर ई मथवा नवाईला हो ॥\n\nगजमोती चउका पुराईला अंचरा बिछाईला हो,\n\nबाबा अँगने में फूलवा त लागेला फलवा न खाईला हो,\n\nबाबा अँगने में फूलवा त लागेला फलवा न खाईला हो ॥\n\nताना देके कहेले गोतीनिया ई बाँझ बा बहिनिया नु हो,\n\nबाबा सुनी सुनी बोलिया गोतीनिया मो लोरवा बहाईला हो,\n\nबाबा सुनी सुनी बोलिया गोतीनिया मो लोरवा बहाईला हो ॥\n\nचुप रहु धीर करूँ दुखिया ना सुन रही कोखिया नु हो,\n\nबस आजु के नव ये महिनावा होरिला मुस्काईला हो,\n\nबस आजु के नव ये महिनावा होरिला मुस्काईला हो,\n\nबाबा फूलवा अक्षतवा चढ़ाईला सब गुण गाईला हो,\n\nबाबा फूलवा अक्षतवा चढ़ाईला सब गुण गाईला हो ॥",
    "meaning": "अनुराधा पौडवाल एवं कविता पौडवाल द्वारा स्वरबद्ध यह अत्यंत भावुक व कालजयी छठ गीत एक निःसंतान व्रती महिला की गहरी पीड़ा और भगवान भास्कर के प्रति अटूट आस्था को दर्शाता है। गोतिनी के तानों से दुखी होकर वह भोर में नदी स्नान कर अक्षत-फूल चढ़ाकर सूर्यदेव से संतान रूपी उजाले की याचना करती है, और छठी मइया व सूर्यदेव की कृपा से नौवें महीने में उसकी गोद हरी होकर होरिला (बालक) मुस्कुराता है।",
