    "festivalPhase": "all",
    "lyrics": "चार पहर हम जल थल सेविले, सेविले चरन तोहार\nहे छठी मईया, सेविले चरन तोहार\nहमरो अरजिया सुन लीं हे छठी माई, करिहें बेड़ा पार\n\nसकल जगत के संकट हरनी, छठी माई दयाल\nगोदी के बालक जुग जुग जिए, मांग में चमके सिंदूर\nमांग में चमके सिंदूर...\n\nअरघ के बेरिया आदित गोसाईं, दर्शन देहें आज\nचार पहर हम जल थल सेविले, सेविले चरन तोहार!"
